"use strict";(self.webpackChunkultimatelearning=self.webpackChunkultimatelearning||[]).push([[802],{802:e=>{e.exports=JSON.parse('{"topic":{"id":"file-handling-basic","title":"File Handling (Basic)","overviewSimple":"Imagine keeping your notes in a notebook so you can read them later. Java file handling is similar \u2014 your program can read from and write to files.","overviewTechnical":["Java uses java.io and java.nio.file packages for file handling.","FileReader and FileWriter handle character streams.","BufferedReader improves reading efficiency.","Files class (NIO) provides modern utilities for reading/writing.","Exceptions like IOException must be handled."],"story":"Tom wrote his homework in a notebook so he could check it later. Java programs also store information in files to use again when needed.","realWorldAnalogy":"A file is like a diary \u2014 you can write entries and read them anytime.","keyPoints":["Supports reading and writing","Uses streams","IOException must be handled","Buffered I/O improves performance"],"exampleSimple":"FileWriter fw = new FileWriter(\\"data.txt\\");\\nfw.write(\\"Hello\\");\\nfw.close();","exampleTechnical":["import java.io.*;\\nclass ReadFile {\\n    public static void main(String[] args) throws Exception {\\n        BufferedReader br = new BufferedReader(new FileReader(\\"data.txt\\"));\\n        System.out.println(br.readLine());\\n        br.close();\\n    }\\n}","import java.nio.file.*;\\npublic class NIOExample {\\n    public static void main(String[] args) throws Exception {\\n        String content = Files.readString(Path.of(\\"info.txt\\"));\\n        System.out.println(content);\\n    }\\n}"],"extraNotes":["Use try-with-resources to auto-close files.","NIO Files API is preferred for modern applications."],"bestPracticesSimple":["Always close files","Keep file names simple"],"bestPracticesAdvanced":["Use try-with-resources for safety","Avoid reading very large files at once","Prefer NIO for faster operations"]}}')}}]);